// FromJSON creates a Theme from JSON data.
// The JSON should contain color definitions and other theme properties.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader creates a Theme from a JSON reader.
// The JSON should contain color definitions and other theme properties.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(reader io.Reader) (fyne.Theme, error) {
	var themeData jsonThemeData
	decoder := json.NewDecoder(reader)

	if err := decoder.Decode(&themeData); err != nil {
		return DefaultTheme(), err
	}

	return &jsonTheme{data: themeData}, nil
}

// parseHexColor converts a hex color string to a color.Color.
// Supports 3, 4, 6, and 8 digit formats (with or without # prefix).
// Short forms (3 and 4 digits) have each digit doubled.
// Returns error if format is invalid.
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint64
	var err error

	switch len(hex) {
	case 3:
		// RGB short form: "abc" -> 0xaa 0xbb 0xcc 0xff
		r, err = strconv.ParseUint(hex[0:1], 16, 8)
		if err != nil {
			return nil, err
		}
		g, err = strconv.ParseUint(hex[1:2], 16, 8)
		if err != nil {
			return nil, err
		}
		b, err = strconv.ParseUint(hex[2:3], 16, 8)
		if err != nil {
			return nil, err
		}
		// Double each digit
		r = r*16 + r
		g = g*16 + g
		b = b*16 + b
		a = 255

	case 4:
		// RGBA short form: "abcd" -> 0xaa 0xbb 0xcc 0xdd
		r, err = strconv.ParseUint(hex[0:1], 16, 8)
		if err != nil {
			return nil, err
		}
		g, err = strconv.ParseUint(hex[1:2], 16, 8)
		if err != nil {
			return nil, err
		}
		b, err = strconv.ParseUint(hex[2:3], 16, 8)
		if err != nil {
			return nil, err
		}
		a, err = strconv.ParseUint(hex[3:4], 16, 8)
		if err != nil {
			return nil, err
		}
		// Double each digit
		r = r*16 + r
		g = g*16 + g
		b = b*16 + b
		a = a*16 + a

	case 6:
		// RGB form: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
		r, err = strconv.ParseUint(hex[0:2], 16, 8)
		if err != nil {
			return nil, err
		}
		g, err = strconv.ParseUint(hex[2:4], 16, 8)
		if err != nil {
			return nil, err
		}
		b, err = strconv.ParseUint(hex[4:6], 16, 8)
		if err != nil {
			return nil, err
		}
		a = 255

	case 8:
		// RGBA form: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
		r, err = strconv.ParseUint(hex[0:2], 16, 8)
		if err != nil {
			return nil, err
		}
		g, err = strconv.ParseUint(hex[2:4], 16, 8)
		if err != nil {
			return nil, err
		}
		b, err = strconv.ParseUint(hex[4:6], 16, 8)
		if err != nil {
			return nil, err
		}
		a, err = strconv.ParseUint(hex[6:8], 16, 8)
		if err != nil {
			return nil, err
		}

	default:
		return nil, errors.New("invalid hex color format")
	}

	return color.NRGBA{R: uint8(r), G: uint8(g), B: uint8(b), A: uint8(a)}, nil
}

